set-variable.value:
@{
        var originalUrl = context.Request.OriginalUrl;
        var scheme = originalUrl.Scheme.ToLowerInvariant();
        var includePort = (scheme == "http" && originalUrl.Port != 80) ||
                          (scheme == "https" && originalUrl.Port != 443);
        var requestUrl = originalUrl.Scheme + "://" +
                         originalUrl.Host +
                         (includePort ? ":" + originalUrl.Port.ToString() : string.Empty) +
                         originalUrl.Path +
                         originalUrl.QueryString;

        // Match the header array produced by the working Node.js example.
        var sidebandHeaders = new JArray();
        sidebandHeaders.Add(
            new JObject(
                new JProperty("Accept", "application/json")
            )
        );
        sidebandHeaders.Add(
            new JObject(
                new JProperty("Content-Type", "application/json")
            )
        );
        sidebandHeaders.Add(
            new JObject(
                new JProperty(
                    "Host",
                    originalUrl.Host +
                    (includePort ? ":" + originalUrl.Port.ToString() : string.Empty)
                )
            )
        );
        sidebandHeaders.Add(
            new JObject(
                new JProperty(
                    "Authorization",
                    context.Request.Headers.GetValueOrDefault("Authorization", string.Empty)
                )
            )
        );

        var serializedBody =
            (string)context.Variables["authorizeOriginalRequestBody"];

        if (!string.IsNullOrEmpty(serializedBody))
        {
            try
            {
                serializedBody = JToken.Parse(serializedBody)
                    .ToString(Newtonsoft.Json.Formatting.None);
            }
            catch
            {
                // Preserve a non-JSON body exactly as received.
            }
        }

        var payload = new JObject(
            new JProperty("source_ip", context.Request.IpAddress ?? string.Empty),
            new JProperty("source_port", 5034),
            new JProperty("method", context.Request.Method),
            new JProperty("url", requestUrl),
            new JProperty("http_version", "1.1"),
            new JProperty("headers", sidebandHeaders),
            new JProperty(
                "body",
                serializedBody
            )
        );

        return payload.ToString(Newtonsoft.Json.Formatting.None);
    }

return-response.set-body:
@{
                    return new JObject(
                        new JProperty("error",
                            new JObject(
                                new JProperty("code", "sideband-unavailable"),
                                new JProperty("message", "Authorization Sideband service is unavailable")
                            )
                        )
                    ).ToString(Newtonsoft.Json.Formatting.None);
                }

@{
                    var response =
                        (IResponse)context.Variables["authorizeSidebandResponse"];
                    var responseHeaders = new JObject();

                    foreach (var header in response.Headers)
                    {
                        responseHeaders[header.Key] = string.Join(", ", header.Value);
                    }

                    var rawBody = response.Body.As<string>(preserveContent: true);
                    JToken responseBody;

                    try
                    {
                        responseBody = JToken.Parse(rawBody);
                    }
                    catch
                    {
                        responseBody = new JValue(rawBody);
                    }

                    var requestBody =
                        JObject.Parse((string)context.Variables["authorizeSidebandRequestBody"]);
                    var requestHeaders = requestBody["headers"] as JArray;

                    if (requestHeaders != null)
                    {
                        foreach (var headerToken in requestHeaders)
                        {
                            var headerObject = headerToken as JObject;
                            if (headerObject != null)
                            {
                                foreach (var property in headerObject.Properties())
                                {
                                    if (property.Name.Equals("authorization", StringComparison.OrdinalIgnoreCase) ||
                                        property.Name.Equals("cookie", StringComparison.OrdinalIgnoreCase) ||
                                        property.Name.Equals("proxy-authorization", StringComparison.OrdinalIgnoreCase))
                                    {
                                        property.Value = "[REDACTED]";
                                    }
                                }
                            }
                        }
                    }

                    return new JObject(
                        new JProperty("error",
                            new JObject(
                                new JProperty("code", "sideband-error"),
                                new JProperty(
                                    "message",
                                    "Authorize returned HTTP " +
                                    ((int)context.Variables["authorizeSidebandHttpStatus"]).ToString()
                                ),
                                new JProperty(
                                    "note",
                                    "Temporary diagnostics are enabled; remove them before production"
                                )
                            )
                        ),
                        new JProperty(
                            "sidebandEndpoint",
                            "{{AuthorizeSidebandRequestEndpoint}}".TrimEnd('/') + "/sideband/request"
                        ),
                        new JProperty("sidebandRequest", requestBody),
                        new JProperty("authorizeResponse",
                            new JObject(
                                new JProperty("statusCode", response.StatusCode),
                                new JProperty("statusReason", response.StatusReason),
                                new JProperty("headers", responseHeaders),
                                new JProperty("body", responseBody)
                            )
                        )
                    ).ToString(Newtonsoft.Json.Formatting.None);
                }

@{
                            return new JObject(
                                new JProperty("error",
                                    new JObject(
                                        new JProperty("code", "sideband-error"),
                                        new JProperty(
                                            "message",
                                            "Authorization service integration error"
                                        )
                                    )
                                )
                            ).ToString(Newtonsoft.Json.Formatting.None);
                        }

set-variable.value:
@{
                var sideband = (JObject)context.Variables["authorizeSidebandBody"];
                var denial = (JObject)sideband["response"];
                int status;

                return Int32.TryParse((string)denial["response_code"], out status)
                    && status >= 100
                    && status <= 599
                        ? status
                        : 403;
            }

@{
                if ((bool)context.Variables["authorizeDebugEnabled"])
                {
                    return "application/json";
                }

                var sideband = (JObject)context.Variables["authorizeSidebandBody"];
                var denial = (JObject)sideband["response"];
                var headers = denial["headers"] as JArray;

                if (headers != null)
                {
                    foreach (var token in headers)
                    {
                        var header = token as JObject;
                        if (header == null)
                        {
                            continue;
                        }

                        var value = header.GetValue(
                            "content-type",
                            StringComparison.OrdinalIgnoreCase
                        );

                        if (value != null)
                        {
                            return (string)value;
                        }
                    }
                }

                return "application/json";
            }

@{
                var sideband = (JObject)context.Variables["authorizeSidebandBody"];
                var denial = (JObject)sideband["response"];
                var headers = denial["headers"] as JArray;

                if (headers != null)
                {
                    foreach (var token in headers)
                    {
                        var header = token as JObject;
                        if (header == null)
                        {
                            continue;
                        }

                        var value = header.GetValue(
                            "www-authenticate",
                            StringComparison.OrdinalIgnoreCase
                        );

                        if (value != null)
                        {
                            return (string)value;
                        }
                    }
                }

                return string.Empty;
            }

@{
                    var sideband = (JObject)context.Variables["authorizeSidebandBody"];
                    var denial = (JObject)sideband["response"];
                    JToken requestId = JValue.CreateNull();

                    try
                    {
                        var originalBody = (string)context.Variables["authorizeOriginalRequestBody"];
                        if (!string.IsNullOrEmpty(originalBody))
                        {
                            var mcp = JObject.Parse(originalBody);
                            if (mcp["id"] != null)
                            {
                                requestId = mcp["id"];
                            }
                        }
                    }
                    catch
                    {
                        // Keep a null JSON-RPC id when the original body isn't JSON.
                    }

                    var status = (int)context.Variables["authorizeDenyStatus"];
                    var reason = (string)context.Variables["authorizeDenyReason"];

                    if ((bool)context.Variables["authorizeDebugEnabled"])
                    {
                        var requestBody =
                            JObject.Parse((string)context.Variables["authorizeSidebandRequestBody"]);
                        var requestHeaders = requestBody["headers"] as JArray;

                        if (requestHeaders != null)
                        {
                            foreach (var headerToken in requestHeaders)
                            {
                                var headerObject = headerToken as JObject;
                                if (headerObject != null)
                                {
                                    foreach (var property in headerObject.Properties())
                                    {
                                        if (property.Name.Equals("authorization", StringComparison.OrdinalIgnoreCase) ||
                                            property.Name.Equals("cookie", StringComparison.OrdinalIgnoreCase) ||
                                            property.Name.Equals("proxy-authorization", StringComparison.OrdinalIgnoreCase))
                                        {
                                            property.Value = "[REDACTED]";
                                        }
                                    }
                                }
                            }
                        }

                        return new JObject(
                            new JProperty("jsonrpc", "2.0"),
                            new JProperty("id", requestId),
                            new JProperty("error",
                                new JObject(
                                    new JProperty("code", status == 401 ? -32001 : -32003),
                                    new JProperty("message", reason),
                                    new JProperty(
                                        "note",
                                        "Temporary Sideband denial diagnostics are enabled"
                                    )
                                )
                            ),
                            new JProperty("sidebandRequest", requestBody),
                            new JProperty("authorizeResponse",
                                new JObject(
                                    new JProperty("statusCode", 200),
                                    new JProperty("statusReason", "OK"),
                                    new JProperty("body", sideband)
                                )
                            )
                        ).ToString(Newtonsoft.Json.Formatting.None);
                    }

                    var denialBody = (string)denial["body"];
                    if (!string.IsNullOrEmpty(denialBody))
                    {
                        return denialBody;
                    }

                    return new JObject(
                        new JProperty("jsonrpc", "2.0"),
                        new JProperty("id", requestId),
                        new JProperty("error",
                            new JObject(
                                new JProperty("code", status == 401 ? -32001 : -32003),
                                new JProperty("message", reason)
                            )
                        )
                    ).ToString(Newtonsoft.Json.Formatting.None);
                }
